from flask import Flask
app = Flask(__name__)
@app.route('/')
def home():
 return """
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mi Negocio 4.0</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"></head>
<body class="bg-[#FFF8F0] min-h-screen"><div class="max-w-md mx-auto pb-[90px]">
<div class="bg-white p-3 flex justify-between items-center sticky top-0 z-20 shadow-sm"><div class="flex items-center gap-2"><label for="logoIn"><img id="logo" src="https://em-content.zobj.net/thumbs/120/apple/354/hamburger_1f354.png" class="w-8 h-8 rounded-full"></label><input id="logoIn" type="file" hidden><h1 class="font-black">Mi Negocio</h1></div><button onclick="tab('clientes')" class="text-[10px] bg-orange-100 px-3 py-1 rounded-full font-bold"><i class="fa-solid fa-users"></i> <span id="cliCount">0</span> Clientes</button></div>

<!-- COSTOS -->
<div id="p-costos" class="p-3">
<div class="bg-white rounded-[24px] p-4 shadow-sm">
<input id="nombre" placeholder="Nombre receta/producto" class="w-full border-2 p-3 rounded-xl font-bold text-sm">
<textarea id="descripcion" placeholder="Descripción para catálogo: Ej Salsa verde cremosa, rinde 1L, picor medio" class="w-full border p-3 rounded-xl text-[12px] mt-2 h-16"></textarea>
<div class="mt-2"><label class="text-[11px] font-bold">Foto del producto:</label><input id="prodImg" type="file" accept="image/*" class="text-[11px] mt-1"><img id="prevImg" class="w-20 h-20 rounded-xl object-cover mt-2 hidden"></div>
<div id="insumos" class="mt-3 space-y-3"></div><button onclick="addInsumo()" class="mt-3 text-[11px] bg-orange-100 px-4 py-2 rounded-full font-bold">+ Ingrediente</button>
<div class="mt-3 p-3 bg-gray-900 text-white rounded-xl text-[12px]"><div class="flex justify-between"><span>Ingredientes</span><span>$<span id="c-ing">0</span></span></div><div class="flex justify-between text-amber-300"><span>+ Fijos</span><span>$<span id="c-fijos">0</span></span></div><div class="flex justify-between font-bold border-t mt-2 pt-2"><span>Total</span>$<span id="costo">0</span> | Venta $<span id="venta">0</span></div><div class="mt-2 flex gap-2"><input id="margen" type="number" value="100" class="w-14 text-black p-2 rounded-lg text-center font-bold text-sm"> % ganancia</div></div>
<button onclick="guardar()" class="w-full mt-3 bg-black text-white py-3 rounded-xl font-black text-sm">Guardar en catálogo</button>
</div><div id="listaInv" class="mt-4"></div>
</div>

<!-- VENDER CATALOGO -->
<div id="p-vender" class="p-3 hidden">
<div class="flex justify-between items-center mb-3"><h2 class="font-black">Catálogo</h2><button onclick="document.getElementById('filtro').classList.toggle('hidden')" class="text-[11px] bg-white px-3 py-1 rounded-full border">Buscar</button></div>
<input id="filtro" placeholder="Buscar producto..." class="hidden w-full border p-3 rounded-xl text-sm mb-3" oninput="mostrarVenta()">
<div id="listaVenta" class="grid grid-cols-2 gap-3"></div>
<div id="carritoBox" class="mt-6 bg-white rounded-[20px] p-4 shadow-xl border">
<div class="flex justify-between"><h3 class="font-bold text-sm">Presupuesto <span id="c-count">0</span></h3><button onclick="vaciar()" class="text-[10px] text-gray-400">Vaciar</button></div>
<div id="c-items" class="text-[12px] mt-2"></div>
<div class="mt-3 border-t pt-3"><label class="text-[11px] font-bold">Cliente:</label><select id="selCliente" class="w-full border p-2.5 rounded-xl text-sm mt-1"><option value="">-- Elige cliente --</option></select><button onclick="tab('clientes')" class="text-[10px] text-orange-600 mt-1">+ Nuevo cliente</button></div>
<div class="flex justify-between font-black text-lg mt-3"><span>Total</span><span>$<span id="c-total">0</span></span></div>
<button onclick="enviarPresupuesto()" class="w-full mt-3 bg-green-500 text-white py-3 rounded-xl font-black text-sm"><i class="fa-brands fa-whatsapp"></i> Mandar presupuesto por WhatsApp</button>
<button onclick="cobrar()" class="w-full mt-2 bg-black text-white py-2.5 rounded-xl text-sm">Cobrar y registrar venta</button>
</div></div>

<!-- FINANZAS -->
<div id="p-finanzas" class="p-3 hidden"><div class="grid grid-cols-3 gap-2"><div class="bg-green-500 text-white p-3 rounded-2xl"><p class="text-[9px]">ENTRADAS</p><p class="font-black">$<span id="f-entradas">0</span></p></div><div class="bg-red-500 text-white p-3 rounded-2xl"><p class="text-[9px]">SALIDAS</p><p class="font-black">$<span id="f-salidas">0</span></p></div><div class="bg-black text-white p-3 rounded-2xl"><p class="text-[9px]">GANANCIA</p><p class="font-black">$<span id="f-ganancia">0</span></p></div></div><div id="f-lista" class="mt-4 bg-white rounded-2xl p-3"></div></div>

<!-- CLIENTES -->
<div id="p-clientes" class="p-3 hidden">
<div class="bg-white rounded-2xl p-4 shadow-sm"><h2 class="font-black text-sm">Base de clientes</h2><div class="mt-3 grid grid-cols-1 gap-2"><input id="cliNombre" placeholder="Nombre" class="border p-3 rounded-xl text-sm"><input id="cliTel" placeholder="WhatsApp 10 dígitos" class="border p-3 rounded-xl text-sm"><input id="cliDir" placeholder="Dirección" class="border p-3 rounded-xl text-sm"><button onclick="addCliente()" class="bg-black text-white py-3 rounded-xl font-bold text-sm">Guardar cliente</button></div></div><div id="listaClientes" class="mt-4 space-y-2"></div>
</div>

<!-- CONFIG FIJOS -->
<div id="p-config" class="p-3 hidden"><div class="bg-white rounded-2xl p-5 shadow-sm"><h2 class="font-black">Gastos fijos</h2><div id="gastosFijos" class="mt-3 space-y-2"></div><button onclick="addGastoFijo()" class="mt-3 w-full bg-gray-100 py-2 rounded-full text-[11px] font-bold">+ Gasto</button><div class="mt-4"><label class="text-[11px] font-bold">¿Cuántos productos al mes?</label><input id="prodMes" type="number" value="100" class="w-full border-2 p-3 rounded-xl mt-1 font-bold" oninput="calcGastosFijos()"></div><div class="mt-3 bg-black text-white p-4 rounded-2xl text-center font-black">$<span id="cfg-porReceta">0</span> por producto</div></div></div>

<div class="fixed bottom-0 left-0 right-0 bg-white border-t flex justify-around py-2 max-w-md mx-auto z-30">
<button onclick="tab('costos')" id="nav-costos" class="flex flex-col items-center px-2 py-1 text-black"><i class="fa-solid fa-calculator text-[14px]"></i><span class="text-[8px] font-bold">Costos</span></button>
<button onclick="tab('vender')" id="nav-vender" class="flex flex-col items-center px-2 py-1 text-gray-300"><i class="fa-solid fa-store text-[14px]"></i><span class="text-[8px]">Catálogo</span></button>
<button onclick="tab('finanzas')" id="nav-finanzas" class="flex flex-col items-center px-2 py-1 text-gray-300"><i class="fa-solid fa-chart-line text-[14px]"></i><span class="text-[8px]">Finanzas</span></button>
<button onclick="tab('clientes')" id="nav-clientes" class="flex flex-col items-center px-2 py-1 text-gray-300"><i class="fa-solid fa-users text-[14px]"></i><span class="text-[8px]">Clientes</span></button>
<button onclick="tab('config')" id="nav-config" class="flex flex-col items-center px-2 py-1 text-gray-300"><i class="fa-solid fa-gear text-[14px]"></i><span class="text-[8px]">Fijos</span></button>
</div>
</div>
<script>
let carrito=[], prodImgBase=''; const U=['kg','g','L','ml','galon','pza','cda'];
function baseFactor(u){ if(u=='kg'||u=='L') return 1000; if(u=='galon') return 3785; return 1;}
document.getElementById('prodImg').onchange=e=>{let r=new FileReader(); r.onload=()=>{prodImgBase=r.result; document.getElementById('prevImg').src=r.result; document.getElementById('prevImg').classList.remove('hidden');}; r.readAsDataURL(e.target.files[0]);};
function addInsumo(d={}){let div=document.createElement('div'); div.className='bg-[#FFF8F0] p-2 rounded-xl border text-[11px]'; div.innerHTML=`<input placeholder="Ingrediente" value="${d.n||''}" class="in-n bg-transparent font-bold text-sm w-full outline-none"><div class="grid grid-cols-3 gap-1 mt-1"><input type="number" value="${d.cc||''}" placeholder="Compra" class="in-cc border p-2 rounded-lg" oninput="calc()"><select class="in-uc border p-2 rounded-lg" onchange="calc()">${U.map(x=>`<option ${d.uc==x?'selected':''}>${x}</option>`).join('')}</select><input type="number" value="${d.pc||''}" placeholder="$" class="in-pc border p-2 rounded-lg" oninput="calc()"><input type="number" value="${d.cu||''}" placeholder="Uso" class="in-cu border p-2 rounded-lg" oninput="calc()"><select class="in-uu border p-2 rounded-lg" onchange="calc()">${U.map(x=>`<option ${d.uu==x?'selected':''}>${x}</option>`).join('')}</select><div class="p-2 bg-white rounded-lg text-center font-bold">$<span class="in-sub">0</span></div></div>`; document.getElementById('insumos').appendChild(div);}
addInsumo({n:'Cebolla',cc:1,uc:'kg',pc:40,cu:150,uu:'g'});
function getGF(){return JSON.parse(localStorage.getItem('gastosFijos')||'[]');} function getProdMes(){return parseFloat(localStorage.getItem('prodMes')||'100')||100;}
function addGastoFijo(d={}){let div=document.createElement('div'); div.className='flex gap-2'; div.innerHTML=`<input value="${d.nombre||''}" placeholder="Renta" class="gf-n flex-1 border p-2 rounded-xl text-sm"><input type="number" value="${d.monto||''}" placeholder="$" class="gf-m w-24 border p-2 rounded-xl text-sm" oninput="calcGastosFijos()"><button onclick="this.parentElement.remove();calcGastosFijos()" class="text-red-300">x</button>`; document.getElementById('gastosFijos').appendChild(div);}
function calcGastosFijos(){let total=0; document.querySelectorAll('#gastosFijos > div').forEach(r=>total+=parseFloat(r.querySelector('.gf-m').value)||0); let prodMes=parseFloat(document.getElementById('prodMes').value)||100; localStorage.setItem('prodMes',prodMes); let arr=[]; document.querySelectorAll('#gastosFijos > div').forEach(r=>arr.push({nombre:r.querySelector('.gf-n').value,monto:parseFloat(r.querySelector('.gf-m').value)||0})); localStorage.setItem('gastosFijos',JSON.stringify(arr)); let por=prodMes>0?total/prodMes:0; document.getElementById('cfg-porReceta').innerText=por.toFixed(2); document.getElementById('c-fijos').innerText=por.toFixed(2); calc();}
function calc(){let tot=0; document.querySelectorAll('#insumos > div').forEach(row=>{let cc=parseFloat(row.querySelector('.in-cc').value)||0, pc=parseFloat(row.querySelector('.in-pc').value)||0, cu=parseFloat(row.querySelector('.in-cu').value)||0, uc=row.querySelector('.in-uc').value, uu=row.querySelector('.in-uu').value; if(!cc||!pc||!cu){row.querySelector('.in-sub').innerText='0'; return;} let cost=(pc/(cc*baseFactor(uc)))*(cu*baseFactor(uu)); if(uc!=uu && (uc=='pza'||uu=='pza')) cost=(pc/cc)*cu; row.querySelector('.in-sub').innerText=cost.toFixed(2); tot+=cost;}); document.getElementById('c-ing').innerText=tot.toFixed(2); let gf=parseFloat(document.getElementById('c-fijos').innerText)||0; document.getElementById('costo').innerText=(tot+gf).toFixed(2); let m=parseFloat(document.getElementById('margen').value)||0; document.getElementById('venta').innerText=((tot+gf)*(1+m/100)).toFixed(2);}
document.getElementById('margen').oninput=calc;
function tab(t){['costos','vender','finanzas','clientes','config'].forEach(x=>{document.getElementById('p-'+x).classList.toggle('hidden',x!=t); document.getElementById('nav-'+x).classList.toggle('text-black',x==t); document.getElementById('nav-'+x).classList.toggle('text-gray-300',x!=t);}); if(t=='vender') mostrarVenta(); if(t=='finanzas') mostrarFinanzas(); if(t=='clientes') mostrarClientes();}
function getProd(){return JSON.parse(localStorage.getItem('productosV2')||'[]');} function getMovs(){return JSON.parse(localStorage.getItem('movs')||'[]');} function getClientes(){return JSON.parse(localStorage.getItem('clientes')||'[]');}
function guardar(){let nombre=document.getElementById('nombre').value.trim(); if(!nombre) return alert('Nombre'); let desc=document.getElementById('descripcion').value; let costo=parseFloat(document.getElementById('costo').innerText), venta=parseFloat(document.getElementById('venta').innerText); let p=getProd(); p.push({id:Date.now(),nombre,descripcion:desc,costo,venta,img:prodImgBase}); localStorage.setItem('productosV2',JSON.stringify(p)); prodImgBase=''; document.getElementById('nombre').value=''; document.getElementById('descripcion').value=''; document.getElementById('prevImg').classList.add('hidden'); mostrar(); tab('vender');}
function mostrar(){let prods=getProd(); let h=''; prods.forEach((p,i)=>h+=`<div class="bg-white p-3 rounded-xl flex gap-3 shadow-sm mt-2"><img src="${p.img||'https://via.placeholder.com/80'}" class="w-12 h-12 rounded-lg object-cover"><div class="flex-1"><b class="text-[12px]">${p.nombre}</b><p class="text-[10px] text-gray-500">${p.descripcion||''}</p><span class="text-[11px]">$${p.costo.toFixed(2)} → $${p.venta.toFixed(2)}</span></div><button onclick="let pr=getProd(); pr.splice(${i},1); localStorage.setItem('productosV2',JSON.stringify(pr)); mostrar();" class="text-red-300 text-xs">X</button></div>`); document.getElementById('listaInv').innerHTML=h; mostrarVenta();}
function mostrarVenta(){let filtro=document.getElementById('filtro').value.toLowerCase(); let prods=getProd().filter(p=>p.nombre.toLowerCase().includes(filtro)); let h=''; prods.forEach(p=>h+=`<button onclick="addCart(${p.id})" class="bg-white rounded-2xl shadow-sm border overflow-hidden text-left"><img src="${p.img||'https://via.placeholder.com/200'}" class="w-full h-24 object-cover"><div class="p-2"><b class="text-[12px] line-clamp-1">${p.nombre}</b><p class="text-[10px] text-gray-500 line-clamp-2 h-7">${p.descripcion||''}</p><p class="text-[11px] text-green-600 font-bold mt-1">$${p.venta.toFixed(2)}</p></div></button>`); document.getElementById('listaVenta').innerHTML=h||'<p class="col-span-2 text-center text-sm text-gray-400">Sin productos</p>'; let cli=getClientes(); let sel=document.getElementById('selCliente'); sel.innerHTML='<option value="">-- Elige cliente --</option>'+cli.map(c=>`<option value="${c.id}">${c.nombre} - ${c.tel}</option>`).join(''); document.getElementById('cliCount').innerText=cli.length;}
function addCart(id){let p=getProd().find(x=>x.id==id); let ex=carrito.find(x=>x.id==id); if(ex) ex.qty++; else carrito.push({...p,qty:1}); renderCart();}
function renderCart(){let t=0,c=0,html=''; carrito.forEach(x=>{t+=x.venta*x.qty; c+=x.qty; html+=`<div class="flex gap-2 py-1 items-center"><img src="${x.img||''}" class="w-8 h-8 rounded object-cover"><div class="flex-1"><span class="font-bold">${x.nombre}</span> x${x.qty}<br><span class="text-[10px] text-gray-400">${x.descripcion||''}</span></div><span>$${(x.venta*x.qty).toFixed(0)}</span></div>`;}); document.getElementById('c-total').innerText=t.toFixed(0); document.getElementById('c-count').innerText=c; document.getElementById('c-items').innerHTML=html||'<span class="text-gray-400 text-xs">Vacío</span>';}
function vaciar(){carrito=[]; renderCart();}
function cobrar(){if(!carrito.length) return alert('Vacío'); let total=parseFloat(document.getElementById('c-total').innerText); let movs=getMovs(); movs.unshift({tipo:'entrada',concepto:'Venta: '+carrito.map(c=>c.nombre+' x'+c.qty).join(', '),monto:total,fecha:new Date().toLocaleString()}); localStorage.setItem('movs',JSON.stringify(movs)); vaciar(); tab('finanzas');}
function enviarPresupuesto(){if(!carrito.length) return alert('Carrito vacío'); let cliId=document.getElementById('selCliente').value; let cli=getClientes().find(c=>c.id==cliId); let tel=cli?cli.tel:''; let nombreCli=cli?cli.nombre:'Cliente'; let texto=`Hola ${nombreCli}!%0A%0A*PRESUPUESTO* - ${new Date().toLocaleDateString()}%0A%0A`; carrito.forEach(p=>{texto+=`• ${p.nombre} x${p.qty} - $${(p.venta*p.qty).toFixed(2)}%0A ${p.descripcion||''}%0A`;}); texto+=`%0A*TOTAL: $${document.getElementById('c-total').innerText}*%0A%0A`; if(cli) texto+=`Entrega: ${cli.direccion}%0A`; texto+=`Gracias por tu preferencia!`; let url=`https://wa.me/52${tel}?text=${texto}`; if(!tel){ url=`https://wa.me/?text=${texto}`; } window.open(url,'_blank');}
function addCliente(){let n=document.getElementById('cliNombre').value.trim(), tel=document.getElementById('cliTel').value.trim(), dir=document.getElementById('cliDir').value.trim(); if(!n||!tel) return alert('Nombre y tel'); let cli=getClientes(); cli.push({id:Date.now().toString(),nombre:n,tel, direccion:dir}); localStorage.setItem('clientes',JSON.stringify(cli)); document.getElementById('cliNombre').value=''; document.getElementById('cliTel').value=''; document.getElementById('cliDir').value=''; mostrarClientes(); mostrarVenta();}
function mostrarClientes(){let cli=getClientes(); let h=''; cli.forEach((c,i)=>h+=`<div class="bg-white p-3 rounded-xl flex justify-between shadow-sm"><div><b class="text-[13px]">${c.nombre}</b><br><span class="text-[11px]">${c.tel}</span><br><span class="text-[10px] text-gray-400">${c.direccion||''}</span></div><button onclick="let cl=getClientes(); cl.splice(${i},1); localStorage.setItem('clientes',JSON.stringify(cl)); mostrarClientes();" class="text-red-300 text-xs">X</button></div>`); document.getElementById('listaClientes').innerHTML=h||'<p class="text-xs text-center text-gray-400">Sin clientes</p>';}
function mostrarFinanzas(){let movs=getMovs(); let ent=0,sal=0,h=''; movs.forEach(m=>{if(m.tipo=='entrada') ent+=m.monto; else sal+=m.monto; h+=`<div class="flex justify-between py-2 border-b"><div><p class="text-[12px] font-bold">${m.concepto}</p><p class="text-[10px] text-gray-400">${m.fecha}</p></div><div class="font-black text-[12px] ${m.tipo=='entrada'?'text-green-600':'text-red-500'}">$${m.monto}</div></div>`;}); document.getElementById('f-entradas').innerText=ent.toFixed(0); document.getElementById('f-salidas').innerText=sal.toFixed(0); document.getElementById('f-ganancia').innerText=(ent-sal).toFixed(0);}
let sGF=getGF(); if(sGF.length) sGF.forEach(g=>addGastoFijo(g)); else {addGastoFijo({nombre:'Renta',monto:3000}); addGastoFijo({nombre:'Luz',monto:800});} document.getElementById('prodMes').value=getProdMes(); calcGastosFijos(); calc(); mostrar(); mostrarClientes(); mostrarFinanzas();
</script></body></html>
""" 
